package in.anumati.platform.notification; import jakarta.persistence.*; import java.time.*; import java.util.*; @Entity @Table(name="notifications") public class Notification{@Id private UUID id;@Column(nullable=false,length=120)private String recipient;@Column(nullable=false,length=40)private String type;@Column(nullable=false,length=200)private String title;@Column(nullable=false,length=2000)private String body;@Column(length=80)private String entityType;private UUID entityId;private Instant readAt;@Column(nullable=false)private Instant createdAt;protected Notification(){}public Notification(String r,String t,String title,String body,String et,UUID ei){id=UUID.randomUUID();recipient=r;type=t;this.title=title;this.body=body;entityType=et;entityId=ei;createdAt=Instant.now();}public UUID getId(){return id;}public String getRecipient(){return recipient;}public String getType(){return type;}public String getTitle(){return title;}public String getBody(){return body;}public String getEntityType(){return entityType;}public UUID getEntityId(){return entityId;}public Instant getReadAt(){return readAt;}public Instant getCreatedAt(){return createdAt;}public void markRead(){readAt=Instant.now();}}
